def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Parse a field starting at position i
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote or the end of the field
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add single quote to field
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Closing quote must be followed by comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        # Move past the comma if present
                        if i < len(line) and line[i] == ',':
                            i += 1
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line while in quoted field - unterminated
                return None
        else:
            # Unquoted field - runs to next comma
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain quotes
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            # Move past the comma if present
            if i < len(line) and line[i] == ',':
                i += 1

    return fields

